const MEMORY_PLANNING=['Planificado','No planificado','Sin determinar'];
const MEMORY_STATES=['Pendiente','En curso','Ocurrido','Cancelado','No realizado','Por aclarar'];
let planScope='upcoming',planView='calendar',memoryPlanning='',memoryType='',memoryPerson='',memoryQuery='',memoryUndated=false,calendarMonth='',calendarDay='',memoryFiltersOpen=false;
try{const savedView=localStorage.getItem('arc-memory-plan-view');if(['agenda','calendar'].includes(savedView))planView=savedView;}catch{}
function memoryDate(x,kind='real'){const value=x[kind==='planned'?'Fecha prevista':'Fecha real'];try{const iso=dateISO(value);if(!/^\d{4}-\d{2}-\d{2}$/.test(iso))return '';const parsed=new Date(iso+'T12:00:00Z');return Number.isFinite(parsed.getTime())&&parsed.toISOString().slice(0,10)===iso?iso:'';}catch{return '';}}
function memoryEnd(x,kind='real'){const start=memoryDate(x,kind),end=memoryDate({'Fecha real':x[kind==='planned'?'Fin previsto':'Fin real']});return end&&end>=start?end:start;}
function memoryRecords(rows){return (rows||[]).filter(x=>x.ID&&(x['Título']||x['Resumen / memoria']||x['Lo previsto']||x['Lo vivido']));}
function memoryState(x){return MEMORY_STATES.includes(x['Estado de realización'])?x['Estado de realización']:'Por aclarar';}
function memoryTimeline(rows,scope,reference=today()){
 return memoryRecords(rows).filter(x=>{const state=memoryState(x),start=memoryDate(x,'planned'),end=memoryEnd(x,'planned');
  if(scope==='history')return state==='Ocurrido';
  if(scope==='review')return state==='Por aclarar';
  if(x.Planificación!=='Planificado')return false;
  if(scope==='allPlans')return true;
  if(scope==='upcoming')return state==='Pendiente'&&!!start&&end>=reference;
  if(scope==='ongoing')return state==='En curso';
  if(scope==='undated')return state==='Pendiente'&&!start;
  if(scope==='confirm')return state==='Pendiente'&&!!start&&end<reference;
  if(scope==='closed')return ['Ocurrido','Cancelado','No realizado'].includes(state);
  return false;
 }).sort((a,b)=>{const kind=scope==='history'?'real':'planned',ad=memoryDate(a,kind),bd=memoryDate(b,kind);if(!ad||!bd)return ad? -1:bd?1:String(a.ID).localeCompare(String(b.ID));const order=ad.localeCompare(bd)||(a['Hora prevista']||'').localeCompare(b['Hora prevista']||'');return (scope==='history'?-order:order)||String(a.ID).localeCompare(String(b.ID));});
}
function memoryMatches(x){return (!memoryPlanning||x.Planificación===memoryPlanning)&&(!memoryType||x.Tipo===memoryType)&&(!memoryPerson||String(x['Personas relacionadas']||'').split(/;\s*/).includes(memoryPerson))&&(!memoryUndated||!memoryDate(x,memoryScope==='plans'?'planned':'real'))&&(!memoryQuery||fold([x['Título'],x['Lo previsto'],x['Lo vivido'],x['Resumen / memoria'],x['Personas relacionadas'],x.Lugar].join(' ')).includes(fold(memoryQuery)));}
function memoryRange(x,kind){const start=memoryDate(x,kind),end=memoryEnd(x,kind),hour=kind==='planned'?x['Hora prevista']:null;return start?niceDate(start,true)+(end&&end!==start?' – '+niceDate(end,true):'')+(hour?' · '+hour:''):'Sin fecha';}
function memoryRow(x,role='history'){const kind=memoryScope==='plans'?'planned':'real',state=memoryState(x),text=role==='history'?(kind==='planned'?x['Lo previsto']:x['Lo vivido'])||x['Resumen / memoria']:x['Motivo / contexto']||x.Notas;return '<div class="history-row"><span class="history-date">'+esc(role==='history'?memoryRange(x,kind):niceDate(x.Fecha||x['Fecha captura'],true))+'</span><button class="history-text" data-detail="'+role+'|'+esc(x.ID)+'"><b>'+esc(x['Título']||x.Idea||x.ID)+'</b><span class="memory-status">'+(role==='history'?esc(state)+(x.Planificación==='Planificado'?' · Planificado':''):'')+'</span><p>'+esc(clip(text,200))+'</p></button></div>';}
function memoryFilters(timeline){const option=(v,label=v)=>'<option value="'+esc(v)+'">'+esc(label)+'</option>',select=(key,label,values,value)=>'<label>'+label+'<select id="'+key+'"><option value="">Todos</option>'+values.map(v=>'<option value="'+esc(v)+'" '+(v===value?'selected':'')+'>'+esc(v)+'</option>').join('')+'</select></label>';const types=[...new Set(timeline.map(x=>x.Tipo).filter(Boolean))].sort(),people=[...new Set(timeline.flatMap(x=>String(x['Personas relacionadas']||'').split(/;\s*/)).filter(Boolean))].sort();return '<div class="memory-filters">'+select('memory-planning','Planificación',MEMORY_PLANNING,memoryPlanning)+select('memory-type','Tipo',types,memoryType)+select('memory-person','Persona',people,memoryPerson)+'<label>Buscar<input id="memory-query" type="search" value="'+esc(memoryQuery)+'" placeholder="Título, lugar o recuerdo"></label>'+(memoryScope==='history'?'<label class="memory-checkbox"><input id="memory-undated" type="checkbox" '+(memoryUndated?'checked':'')+'>Solo sin fecha</label>':'')+'<button class="text-button" data-memory-reset="true">Limpiar filtros</button></div>';}
function calendarDays(month){const first=new Date(month+'-01T12:00:00Z'),offset=(first.getUTCDay()+6)%7,start=new Date(first);start.setUTCDate(1-offset);return Array.from({length:42},(_,i)=>{const d=new Date(start);d.setUTCDate(start.getUTCDate()+i);return d.toISOString().slice(0,10);});}
let calendarFocus=true,memoryOverlay='',focusReadError='';
try{calendarFocus=localStorage.getItem('arc-memory-calendar-focus-v1')!=='false';}catch{}
function isCalendarFocused(){return view==='memoria'&&memoryScope==='plans'&&planView==='calendar'&&calendarFocus&&!!data&&(!external||external.ready());}
function setCalendarFocus(enabled){calendarFocus=enabled;try{localStorage.setItem('arc-memory-calendar-focus-v1',String(enabled));}catch{}render();window.scrollTo({top:0,behavior:'instant'});}
