function memory(){if(isCalendarFocused())return memoryFocusView();const timeline=memoryRecords(data.history),review=memoryTimeline(timeline,'review'),tabs=[['history','Lo vivido'],['plans','Planes'],['recommendations','Recomendaciones'],['ideas','Ideas'],...(review.length?[['review','Por aclarar · '+review.length]]:[])];if(!tabs.some(([scope])=>scope===memoryScope))memoryScope='history';const extra=['recommendations','ideas'].includes(memoryScope),plans=memoryScope==='plans',scope=plans?planScope:memoryScope,rows=extra?(data[memoryScope]||[]).filter(x=>x.ID):memoryTimeline(timeline,scope).filter(memoryMatches);const scopes=[['upcoming','Lo próximo'],['ongoing','En curso'],['undated','Sin fecha'],['confirm','Pendientes de confirmar'],['closed','Cerrados'],['allPlans','Todos']];let body='';if(plans)body+='<div class="memory-plan-toolbar"><div class="filter-chips">'+scopes.map(([s,label])=>'<button class="chip '+(planScope===s?'active':'')+'" data-plan-scope="'+s+'">'+label+' <small>'+memoryTimeline(timeline,s).filter(memoryMatches).length+'</small></button>').join('')+'</div><div class="memory-view-switch" role="group" aria-label="Vista de planes">'+[['agenda','Agenda'],['calendar','Calendario']].map(([v,label])=>'<button class="chip '+(planView===v?'active':'')+'" data-plan-view="'+v+'" aria-pressed="'+(planView===v)+'">'+label+'</button>').join('')+'</div></div>';if(plans&&planView==='calendar')body+='<button class="button light calendar-expand" data-calendar-focus="true">Ampliar calendario</button>';if(!extra)body+='<details class="memory-filter-panel" id="memory-filter-panel" '+(memoryFiltersOpen?'open':'')+'><summary>Filtros'+([memoryPlanning,memoryType,memoryPerson,memoryQuery,memoryUndated].some(Boolean)?' · activos':'')+'</summary>'+memoryFilters(timeline)+'</details>';body+='<p class="memory-filter-note">'+(memoryScope==='history'?'Experiencias confirmadas · De más reciente a más antigua':memoryScope==='review'?'Clasificación pendiente; no se presupone que ocurrieran':plans?'La fecha no confirma la realización':'Registros guardados')+' · '+rows.length+(rows.length===1?' registro':' registros')+'</p>';body+=plans&&planView==='calendar'?memoryCalendar(rows):'<div class="panel">'+(rows.length?rows.map(x=>memoryRow(x,extra?memoryScope:'history')).join(''):empty('No hay registros en esta vista','Prueba otro filtro.'))+'</div>';return '<div class="memory-view">'+heading('Memoria')+'<div class="memory-tabs" role="tablist" aria-label="Filtrar memoria">'+tabs.map(([scope,label])=>'<button id="memory-tab-'+scope+'" role="tab" aria-selected="'+(memoryScope===scope)+'" aria-controls="memory-panel" class="chip '+(memoryScope===scope?'active':'')+'" data-memory-scope="'+scope+'">'+label+'</button>').join('')+'</div><div id="memory-panel" role="tabpanel" aria-labelledby="memory-tab-'+memoryScope+'">'+body+'</div></div>';}
