function sortedIncoming(rows,mode=incomingSort){
 const stamp=x=>{const v=x['Fecha captura'];return typeof v==='number'?(v-25569)*86400000:v?Date.parse(v):NaN;};
 return [...rows].sort((a,b)=>{const tie=String(a.ID).localeCompare(String(b.ID));if(mode==='newest'||mode==='oldest'){const x=stamp(a),y=stamp(b);if(!Number.isFinite(x)||!Number.isFinite(y))return Number.isFinite(x)?-1:Number.isFinite(y)?1:tie;return (mode==='newest'?y-x:x-y)||tie;}return (Number.isFinite(a['Orden manual'])?a['Orden manual']:Infinity)-(Number.isFinite(b['Orden manual'])?b['Orden manual']:Infinity)||tie;});
}
function incoming(){const rows=sortedIncoming(data.incoming);return heading('Incoming','Entradas guardadas que aún no se han consolidado.')+`<div class="task-toolbar"><label>Ordenar<select id="incoming-sort">${[['manual','Mi orden'],['newest','Más recientes primero'],['oldest','Más antiguas primero']].map(([v,l])=>`<option value="${v}" ${incomingSort===v?'selected':''}>${l}</option>`).join('')}</select></label></div>${data.incomingOrdering&&incomingSort==='manual'?'<p class="filter-info">Usa las flechas para mover entradas. Tu orden se guarda para todos tus dispositivos.</p>':''}`+(rows.length?rows.map((x,i)=>`<article class="incoming-card"><header><span>${esc(x.ID)} · ${esc(niceDate(x['Fecha captura']))}</span><span class="pill amber">${esc(x.Estado)}</span></header><p>${esc(x['Texto original'])}</p>${reviewBadge(x)}<div class="dialog-actions"><button class="text-button" data-detail="incoming|${esc(x.ID)}">Ver referencias y recibos</button>${data.incomingOrdering&&live&&incomingSort==='manual'?`<button class="text-button" data-move-incoming="${esc(x.ID)}|up" aria-label="Subir ${esc(x.ID)}" ${busy||i===0?'disabled':''}>↑</button><button class="text-button" data-move-incoming="${esc(x.ID)}|down" aria-label="Bajar ${esc(x.ID)}" ${busy||i===rows.length-1?'disabled':''}>↓</button>`:''}</div></article>`).join(''):empty('Nada pendiente de consolidar','La información ya procesada conserva su trazabilidad en la hoja.','inbox'))+`<div class="secondary-section"><button class="button light" data-copy-prompt="Procesa las entradas pendientes de Incoming del sistema personal, respetando su orden manual y verificando sus destinos antes de cerrarlas.">${icon('copy')}Copiar petición de consolidación</button></div>`;}
function vacationView(){return '<div id="vacation-root"></div>';}
function modules(){return `<button class="resource-link" data-view="vacaciones"><span class="tile-icon">${icon('plane')}</span><span class="row-info"><b>Vacaciones</b><small>Agenda y planes del viaje</small></span>${icon('arrow')}</button>`+heading('Tus módulos','Accesos a los destinos actuales del sistema.')+`<div class="resource-list">${data.modules.map(m=>`<a class="resource-link" href="${esc(safeURL(m.URL))}" target="_blank" rel="noopener noreferrer"><span class="tile-icon">${icon('grid')}</span><span class="row-info"><b>${esc(m.Dominio)}</b><small>${esc(m['Backend canónico'])}</small></span>${icon('arrow')}</a>`).join('')}</div><p class="subtitle secondary-section">Entrenamiento y Salud se abren en sus hojas originales. Sus datos no se copian a este panel.</p>`;}
