function searchItems(){return ['tasks','archivedTasks','projects','people','incoming','history','recommendations','ideas'].flatMap(role=>(data[role]||[]).filter(x=>x.ID).map(x=>({role,id:x.ID,title:x.Tarea||x.Nombre||x['Título']||x.Idea||x.ID,text:Object.entries(x).filter(([k])=>!k.startsWith('_')).map(([,v])=>v??'').join(' '),label:role==='history'?(memoryState(x)==='Ocurrido'?'Vivencia':x.Planificación==='Planificado'?'Plan':'Registro'):({tasks:'Tarea',archivedTasks:'Tarea archivada',projects:'Proyecto',people:'Persona',incoming:'Incoming',recommendations:'Recomendación',ideas:'Idea'})[role]})));}
function search(){if(!q.trim())return heading('¿Qué quieres recuperar?','Busca palabras, nombres o el identificador de un registro.')+empty('Todo a mano','Tareas, proyectos, personas, recuerdos y entradas por consolidar.','search');const words=fold(q).trim().split(/\s+/);const items=searchItems().filter(x=>(searchScope==='all'||x.role===searchScope)&&words.every(w=>fold(x.title+' '+x.text+' '+x.id).includes(w)));return heading('Resultados para «'+q+'»',items.length+' coincidencias en los registros consultados.')+`<div class="filter-chips">${[['all','Todo'],['tasks','Tareas'],['people','Personas'],['projects','Proyectos'],['incoming','Incoming'],['history','Memoria']].map(([s,l])=>`<button class="chip ${searchScope===s?'active':''}" data-search-scope="${s}">${l}</button>`).join('')}</div>`+(items.length?items.map(x=>`<button class="query-result" data-detail="${esc(x.role)}|${esc(x.id)}"><small>${esc(x.label)} · ${esc(x.id)}</small><b>${esc(x.title)}</b><p>${esc(clip(x.text,220))}</p></button>`).join(''):empty('No encuentro coincidencias','Prueba con menos palabras o busca en la hoja original. El HUB no sustituye una revisión de contexto en ChatGPT.','search'));}
function connection(){return heading('Conexión y alcance')+`<div class="connection-grid"><section class="connection-box"><span class="connection-state ${live?'live':''}">${live?'Conexión con Google activa':'Vista previa · Conexión pendiente'}</span>${external?'<button class="text-button" id="disconnect-google">Desconectar de este dispositivo</button>':''}<h2>Tus datos siguen en Sheets</h2><p>${live?'Cada lectura consulta el backend actual. Una captura solo se confirma después de leer de vuelta su ID y su texto.':'Esta copia fechada permite explorar la interfaz y preparar un borrador.'}</p><table class="choice-table"><tr><th>Dispositivo</th><th>Prioridad</th></tr><tr><td>Móvil</td><td>Capturar, buscar y consultar.</td></tr><tr><td>Ordenador</td><td>Revisar tareas, proyectos, personas y memoria con más contexto.</td></tr></table></section><section class="connection-box"><div class="eyebrow">Datos actualizados</div><h2>Una misma base en tus dispositivos</h2><p>El HUB conectado actualiza al abrir, al volver a la pantalla, después de guardar y cada 30 segundos mientras está visible. Los cambios externos aparecen en la siguiente lectura que tenga éxito.</p><p>El borrador temporal pertenece a este navegador. La entrada pasa al sistema al confirmar su guardado en Incoming.</p></section><section class="connection-box"><div class="eyebrow">Uso cotidiano</div><h2>Captura, consulta y edición</h2><p>Las ideas, recuerdos y el contexto van a Incoming. Pide «procesa las entradas» en ChatGPT cuando quieras consolidarlas.</p><p>Las urgencias, compromisos con fecha, correcciones y cierres se atienden directamente en ChatGPT o en su registro.</p><p>La búsqueda encuentra palabras en tus registros. Las fichas de tarea permiten editar sus campos, cerrar y reabrir. Tus cambios quedan marcados para la siguiente revisión del sistema, cuando se la pidas en ChatGPT.</p><p>Los módulos conservan sus fuentes y aparecen como accesos.</p></section></div>`;}
