function render(){document.body?.classList?.toggle('calendar-focus',isCalendarFocused());document.title=(names[view]||'Inicio')+' · ARC';nav();const appsVisible=view==='apps'&&window.ARC_APPS&&window.location?.hostname!=='hexabor.github.io';if($('main'))$('main').hidden=!!appsVisible;if(appsVisible){window.ARC_APPS.show($('apps-root'));return;}window.ARC_APPS?.hide();if(external&&!external.ready()){$('main').innerHTML=heading('Tu espacio personal')+`<section class="connection-box"><h2>${external.configured?'Conecta con Google':'La migración está preparada'}</h2><p>${external.configured?'Tus datos se cargarán desde tu sistema privado.':'Esta versión todavía necesita activar su conexión. El HUB anterior sigue siendo tu acceso operativo.'}</p>${external.configured?'<button class="button dark" id="connect-google">Conectar con Google</button>':''}</section>`;return;}if(!data){$('main').innerHTML='<div class="loading">Leyendo tus datos…</div>';return;}$('main').innerHTML=(taskDraft&&!isCalendarFocused()?'<div class="connection-box"><p>Hay una edición sin guardar conservada en esta pestaña.</p><button class="button light" id="recover-task-draft">Recuperar edición</button></div>':'')+(renderers[view]||home)();hydrateIcons();if(view==='vacaciones'&&window.ARC_VACATION)window.ARC_VACATION.mount($('vacation-root'),(name,...args)=>{if(external)return external.call(name,...args);return new Promise((resolve,reject)=>google.script.run.withSuccessHandler(resolve).withFailureHandler(reject)[name](...args));});document.title=(names[view]||'Inicio')+' · ARC';}
