function direct(){lastFocus=document.activeElement;$('detail-type').textContent='Atender directamente';$('detail-content').innerHTML=`<h2 id="detail-title">Esto necesita una acción.</h2><p>Para una urgencia, un compromiso con fecha, una corrección o un cierre, utiliza ChatGPT o el registro correspondiente. Una entrada en Incoming quedaría esperando a que la consolides.</p><div class="dialog-actions"><button class="button dark" id="copy-direct">${icon('copy')}Copiar mi texto</button><a class="button light" href="${source('tasks')}" target="_blank" rel="noopener noreferrer">Abrir tareas</a></div>`;$('detail-dialog').showModal();}
