async function moveTask(id,direction){if(busy||!data.taskEditing)return;const global=sortedTasks(taskList(),'manual'),visible=global.filter(t=>matchesTask(t)),index=visible.findIndex(t=>t.ID===id),other=visible[index+(direction==='up'?-1:1)];if(!other)return;let payload=orderRequest;if(!payload){const ids=global.map(t=>t.ID),a=ids.indexOf(id),b=ids.indexOf(other.ID);[ids[a],ids[b]]=[ids[b],ids[a]];payload={ids,versions:Object.fromEntries(global.map(t=>[t.ID,t._version])),requestId:newKey()};orderRequest=payload;}busy=true;render();try{const r=await rpc('reorderTasks',payload);if(!r?.verified)throw new Error('El orden no está confirmado.');orderRequest=null;toast('Orden guardado');}catch(error){toast(error.message||'No se ha confirmado el orden.');if(/cambió|cambiaron|cambiado/.test(error.message||''))orderRequest=null;}finally{busy=false;await refresh();}}
