 let payload=incomingOrderRequest;if(!payload){const ids=rows.map(r=>r.ID);[ids[index],ids[other]]=[ids[other],ids[index]];payload={ids,versions:Object.fromEntries(rows.map(r=>[r.ID,r._version])),requestId:newKey()};incomingOrderRequest=payload;}
 busy=true;render();try{const receipt=await rpc('reorderIncoming',payload);if(!receipt?.verified)throw new Error('El orden no está confirmado.');incomingOrderRequest=null;toast('Orden de Incoming guardado');}catch(error){toast(error.message||'No se ha confirmado el orden.');if(/cambi[oó]|cambiaron|cambió/.test(error.message||''))incomingOrderRequest=null;}finally{busy=false;await refresh();}
