async function copy(text){try{await navigator.clipboard.writeText(text);return true;}catch{const area=document.createElement('textarea');area.value=text;area.style.position='fixed';area.style.left='-9999px';document.body.append(area);area.select();const ok=document.execCommand('copy');area.remove();return ok;}}
function rpc(method,...args){if(external)return external.call(method,...args);return new Promise((resolve,reject)=>{if(!live){reject(new Error('Conexión pendiente de activar.'));return;}google.script.run.withSuccessHandler(resolve).withFailureHandler(reject)[method](...args);});}
