async function submit(event){event.preventDefault();if(busy)return;const text=$('capture-text').value;if(!text.trim()){toast('Escribe primero lo que quieres capturar.');$('capture-text')?.focus();return;}draft.text=text;saveDraft();if(!live){const ok=await copy(text);$('capture-result').textContent=ok?'Copiado. Pégalo en este proyecto de ChatGPT para incorporarlo al sistema.':'No he podido copiarlo. Selecciona el texto y cópialo manualmente.';return;}
 busy=true;$('capture-submit').disabled=true;$('capture-submit').textContent='Guardando…';$('capture-text').disabled=true;try{if(refreshPromise)await refreshPromise;const receipt=await rpc('captureIncoming',{text,requestId:draft.key});if(!receipt?.verified||!receipt.id)throw new Error('No se ha podido verificar el guardado. Conserva el borrador y reintenta.');draft={text:'',key:newKey()};saveDraft();busy=false;captureOpen=false;toast('Guardado y verificado en Incoming · '+receipt.id);await refresh();if($('capture-text')){$('capture-text').value='';$('capture-result').textContent='Guardado y verificado · '+receipt.id;}}catch(e){const message=e.message||'No se ha podido guardar. El borrador se conserva.';if($('capture-result'))$('capture-result').textContent=message;else toast(message);}finally{busy=false;if($('capture-text'))$('capture-text').disabled=false;if($('capture-submit')){$('capture-submit').disabled=false;$('capture-submit').innerHTML=icon('plus')+'Guardar en Incoming';}}}
document.addEventListener('click',async event=>{const link=event.target.closest('a[data-module-key]');if(link?.dataset.moduleKey){rememberModule(link.dataset.moduleKey);setTimeout(nav,0);return;}const e=event.target.closest('button,[data-detail]');if(!e)return;if(e.dataset.moveIncoming){await moveIncoming(...e.dataset.moveIncoming.split('|'));return;}if(e.dataset.moveTask){await moveTask(...e.dataset.moveTask.split('|'));return;}if(e.id==='recover-task-draft'){const saved=taskDraft,found=data.tasks?.find(t=>t.ID===saved.editor.id)||data.archivedTasks?.find(t=>t.ID===saved.editor.id)||data.history?.find(t=>t.ID===saved.editor.id);if(!found){toast('No se encuentra el registro. Consulta su fuente antes de repetir el cambio.');return;}taskEditor=saved.editor;lastFocus=document.activeElement;$('detail-type').textContent=(taskEditor.role==='history'?'Memoria':'Tarea')+' · '+taskEditor.id;editTaskForm();$('task-edit-form').querySelectorAll('[data-field]').forEach(el=>el.value=saved.values[el.dataset.field]??'');$('detail-dialog').showModal();return;}if(e.id==='edit-task'){editTaskForm();return;}if(e.id==='cancel-task-edit'){if(taskEditor?.dirty&&!window.confirm('¿Descartar los cambios de esta ficha?'))return;const {role,id}=taskEditor;taskEditor=null;taskDraft=null;$('detail-dialog').close();openDetail(role,id);return;}if(e.dataset.homeApp){setView('apps',e.dataset.homeApp);return;}if(e.dataset.view){setView(e.dataset.view);return;}if(e.hasAttribute('data-capture')){openCapture();return;}if(e.dataset.detail){openDetail(...e.dataset.detail.split('|'));return;}if(e.dataset.project){if($('detail-dialog').open)closeDetail();filter.project=e.dataset.project;setView('tareas');return;}if(e.dataset.projectScope){projectScope=e.dataset.projectScope;render();return;}if(e.dataset.memoryScope){memoryScope=e.dataset.memoryScope;memoryUndated=false;render();return;}if(e.dataset.calendarFocus){setCalendarFocus(e.dataset.calendarFocus==='true');return;}if(e.dataset.calendarFilters){openMemoryOverlay('filters');return;}if(e.dataset.calendarUndated){openMemoryOverlay('undated');return;}if(e.dataset.calendarRefresh){await refresh();return;}if(e.dataset.planScope){planScope=e.dataset.planScope;calendarDay='';render();return;}if(e.dataset.planView){planView=e.dataset.planView;try{localStorage.setItem('arc-memory-plan-view',planView);}catch{}render();return;}if(e.dataset.calendarMove){const d=new Date((calendarMonth||today().slice(0,7))+'-15T12:00:00Z');d.setUTCMonth(d.getUTCMonth()+Number(e.dataset.calendarMove));calendarMonth=d.toISOString().slice(0,7);calendarDay='';render();return;}if(e.dataset.calendarToday){calendarMonth=today().slice(0,7);calendarDay=today();render();return;}if(e.dataset.calendarDay){calendarDay=e.dataset.calendarDay;if(isCalendarFocused())openMemoryOverlay('day',calendarDay);else render();return;}if(e.dataset.memoryReset){memoryPlanning=memoryType=memoryPerson=memoryQuery='';memoryUndated=false;render();if(memoryOverlay==='filters'&&$('detail-dialog').open)openMemoryOverlay('filters');return;}if(e.dataset.searchScope){searchScope=e.dataset.searchScope;render();return;}if(e.hasAttribute('data-direct')){direct();return;}if(e.dataset.copyPrompt){toast(await copy(e.dataset.copyPrompt)?'Petición copiada. Pégala en tu proyecto de ChatGPT.':'No se ha podido copiar la petición.');return;}if(e.id==='copy-direct'){toast(draft.text.trim()?(await copy(draft.text)?'Texto copiado. Pégalo en tu proyecto de ChatGPT.':'No se ha podido copiar.'):'Primero escribe tu texto en captura.');return;}if(e.id==='connect-google'){try{external.connect();}catch(error){toast(error.message);}return;}if(e.id==='disconnect-google'){external.disconnect();return;}if(e.id==='retry-load')refresh();});
document.addEventListener('input',e=>{if(e.target.id==='memory-query'&&memoryOverlay==='filters'){memoryQuery=e.target.value;render();return;}if(e.target.closest?.('#task-edit-form')){taskEditor.dirty=true;if(taskEditor.pending){taskEditor.pending=null;$('task-edit-status').textContent='Comprueba el último guardado en la fuente antes de enviar cambios distintos.';}}if(e.target.id==='capture-text'){draft.text=e.target.value;const saved=saveDraft();$('draft-status').textContent=saved?'Borrador en este dispositivo':'Borrador solo en esta pestaña';$('char-count').textContent=draft.text.length+' / 12.000';}if(e.target.id==='global-search'){q=e.target.value;view='buscar';render();}});
