document.addEventListener('toggle',e=>{if(e.target.id==='memory-filter-panel')memoryFiltersOpen=e.target.open;if(e.target.id==='capture-panel')captureOpen=e.target.open;const id=e.target.dataset?.moduleSection;if(id){if(e.target.open)openSections.add(id);else openSections.delete(id);try{localStorage.setItem(sectionsKey,JSON.stringify([...openSections]));}catch{}}},true);
