document.addEventListener('keydown',e=>{const tab=e.target.closest?.('[role=tab][data-memory-scope]');if(tab&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){const tabs=[...document.querySelectorAll('[role=tab][data-memory-scope]')],index=tabs.indexOf(tab),next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(index+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;e.preventDefault();memoryScope=tabs[next].dataset.memoryScope;render();$('memory-tab-'+memoryScope)?.focus();return;}if(e.key==='Escape'&&isCalendarFocused()&&!$('detail-dialog').open){e.preventDefault();setCalendarFocus(false);return;}if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||$('detail-dialog').open||document.querySelector('#vac-dialog[open]'))return;if(e.key==='/'){e.preventDefault();if(isCalendarFocused())setView('buscar');else $('global-search').focus();}if(e.key.toLowerCase()==='n'){e.preventDefault();openCapture();}});
